319	    /// <param name="messageChannel">The message channel where messages should be enqueued.</param>
320	    private void EnqueueStepMessages(LocalStep step, Queue<ProcessMessage> messageChannel)
321	    {
322	        var allStepEvents = step.GetAllEvents();
323	        foreach (ProcessEvent stepEvent in allStepEvents)
324	        {
325	            // Emit the event out of the process (this one) if it's visibility is public.
326	            if (stepEvent.Visibility == KernelProcessEventVisibility.Public)
327	            {
328	                base.EmitEvent(stepEvent);
329	            }
330	
331	            // Get the edges for the event and queue up the messages to be sent to the next steps.
332	            bool foundEdge = false;
333	            foreach (KernelProcessEdge edge in step.GetEdgeForEvent(stepEvent.Id))
334	            {
335	                ProcessMessage message = ProcessMessageFactory.CreateFromEdge(edge, stepEvent.Data);
336	                messageChannel.Enqueue(message);
337	                foundEdge = true;
338	            }
339	
340	            // Error event was raised with no edge to handle it, send it to an edge defined as the global error target.
341	            if (!foundEdge && stepEvent.IsError)
342	            {
343	                if (this._outputEdges.TryGetValue(ProcessConstants.GlobalErrorEventId, out List<KernelProcessEdge>? edges))
344	                {
345	                    foreach (KernelProcessEdge edge in edges)
346	                    {
347	                        ProcessMessage message = ProcessMessageFactory.CreateFromEdge(edge, stepEvent.Data);
348	                        messageChannel.Enqueue(message);
349	                    }
350	                }
351	            }
352	        }
353	    }
