388	    internal async ValueTask EmitEventAsync(ProcessEvent daprEvent)
389	    {
390	        // Emit the event out of the process (this one) if it's visibility is public.
391	        if (daprEvent.Visibility == KernelProcessEventVisibility.Public)
392	        {
393	            if (this.ParentProcessId is not null)
394	            {
395	                // Emit the event to the parent process
396	                var parentProcess = this.ProxyFactory.CreateActorProxy<IEventBuffer>(new ActorId(this.ParentProcessId), nameof(EventBufferActor));
397	                await parentProcess.EnqueueAsync(daprEvent).ConfigureAwait(false);
398	            }
399	        }
400	
401	        // Get the edges for the event and queue up the messages to be sent to the next steps.
402	        bool foundEdge = false;
403	        foreach (var edge in this.GetEdgeForEvent(daprEvent.Id))
404	        {
405	            ProcessMessage message = ProcessMessageFactory.CreateFromEdge(edge, daprEvent.Data);
406	            var scopedStepId = this.ScopedActorId(new ActorId(edge.OutputTarget.StepId));
407	            var targetStep = this.ProxyFactory.CreateActorProxy<IMessageBuffer>(scopedStepId, nameof(MessageBufferActor));
408	            await targetStep.EnqueueAsync(message).ConfigureAwait(false);
