namespace Microsoft.SemanticKernel.Process.Runtime;

/// <summary>
/// A wrapper around <see cref="KernelProcessEvent"/> that helps to manage the namespace of the event.
/// </summary>
public record ProcessEvent
{
    /// <summary>
    /// The namespace of the event.
    /// </summary>
    public string? Namespace { get; init; }

    /// <summary>
    /// The Id of the source that emitted the event.
    /// </summary>
    public string SourceId { get; init; } = string.Empty;

    /// <summary>
    /// An optional data payload associated with the event.
    /// </summary>
    public object? Data { get; init; }

    /// <summary>
    /// The visibility of the event.
    /// </summary>
    public KernelProcessEventVisibility Visibility { get; init; } = KernelProcessEventVisibility.Internal;

    /// <summary>
    /// This event represents a runtime error / exception raised internally by the framework.
    /// </summary>
    public bool IsError { get; init; }

    /// <summary>
    /// The fully qualified Id of the event, scoped by its namespace.
    /// </summary>
    internal string QualifiedId => $"{this.Namespace}.{this.SourceId}";

    /// <summary>
    /// Factory method to create a <see cref="ProcessEvent"/> from a <see cref="KernelProcessEvent"/>.
    /// </summary>
    /// <param name="kernelProcessEvent">The source <see cref="KernelProcessEvent"/>.</param>
    /// <param name="eventNamespace">The namespace of the event.</param>
    /// <param name="isError">Indicates whether the event represents a runtime error.</param>
    /// <returns>An instance of <see cref="ProcessEvent"/>.</returns>
    public static ProcessEvent Create(KernelProcessEvent kernelProcessEvent, string eventNamespace, bool isError = false) =>
        new()
        {
            Namespace = eventNamespace,
            SourceId = kernelProcessEvent.Id,
            Data = kernelProcessEvent.Data,
            Visibility = kernelProcessEvent.Visibility,
            IsError = isError,
