using System;
using System.Text.Json;

namespace Microsoft.SemanticKernel.Process.Serialization;

/// <summary>
/// Extension methods for capturing and restoring an object's type.
/// </summary>
internal static class TypeInfo
{
    /// <summary>
    /// Captures the assembly-qualified type name of the provided value.
    /// </summary>
    /// <param name="value">The value whose type is being captured.</param>
    /// <returns>The assembly-qualified type name, or <see langword="null"/> when the value is <see langword="null"/>.</returns>
    public static string? GetAssemblyQualifiedType(object? value)
    {
        if (value is null)
        {
            return null;
        }

        return value.GetType().AssemblyQualifiedName;
    }

    /// <summary>
    /// Restores an object's type from the captured type name.
    /// </summary>
    /// <param name="assemblyQualifiedTypeName">The assembly-qualified type name captured during serialization.</param>
    /// <param name="value">The deserialized value. Only <see cref="JsonElement"/> values are converted.</param>
    /// <returns>The value restored to its original type.</returns>
    public static object? ConvertValue(string? assemblyQualifiedTypeName, object? value)
    {
        // Only a JsonElement requires conversion. Any other value is already the correct type.
        if (value is not JsonElement element)
        {
            return value;
        }

        if (assemblyQualifiedTypeName is null)
        {
            throw new KernelException("Unable to restore data that was persisted without type information.");
        }

        Type? valueType = Type.GetType(assemblyQualifiedTypeName);
        if (valueType is null)
        {
            throw new KernelException($"Unable to load the type required for deserialization: {assemblyQualifiedTypeName}");
        }

        return element.Deserialize(valueType);
    }
}
