using System.Collections.Generic;
using System.Linq;
using System.Text.Json;

namespace Microsoft.SemanticKernel.Process.Serialization;

/// <summary>
/// Serializer for <see cref="KernelProcessEvent"/> objects. Includes type info for <see cref="KernelProcessEvent.Data"/>.
/// </summary>
internal static class KernelProcessEventSerializer
{
    /// <summary>
    /// Serializes a <see cref="KernelProcessEvent"/> to JSON, capturing type information for its <see cref="KernelProcessEvent.Data"/>.
    /// </summary>
    /// <param name="processEvent">The event to serialize.</param>
    /// <returns>The serialized JSON string.</returns>
    public static string ToJson(this KernelProcessEvent processEvent)
    {
        EventContainer<KernelProcessEvent> containedEvents = new(TypeInfo.GetAssemblyQualifiedType(processEvent.Data), processEvent);
        return JsonSerializer.Serialize(containedEvents);
    }

    /// <summary>
    /// Deserializes a set of JSON strings back into <see cref="KernelProcessEvent"/> objects, restoring the type of each <see cref="KernelProcessEvent.Data"/>.
    /// </summary>
    /// <param name="jsonEvents">The JSON strings to deserialize.</param>
    /// <returns>The deserialized events.</returns>
    /// <exception cref="KernelException">Thrown if any event fails deserialization.</exception>
    public static IList<KernelProcessEvent> ToKernelProcessEvents(this IEnumerable<string> jsonEvents)
    {
        return Deserialize().ToArray();

        IEnumerable<KernelProcessEvent> Deserialize()
        {
            foreach (string json in jsonEvents)
            {
                yield return json.ToKernelProcessEvent();
            }
        }
    }

    /// <summary>
    /// Deserializes a single JSON string back into a <see cref="KernelProcessEvent"/>, restoring the type of its <see cref="KernelProcessEvent.Data"/>.
    /// </summary>
    /// <param name="jsonEvent">The JSON string to deserialize.</param>
    /// <returns>The deserialized event.</returns>
    /// <exception cref="KernelException">Thrown if the event fails deserialization.</exception>
    public static KernelProcessEvent ToKernelProcessEvent(this string jsonEvent)
    {
        EventContainer<KernelProcessEvent> eventContainer =
            JsonSerializer.Deserialize<EventContainer<KernelProcessEvent>>(jsonEvent) ??
            throw new KernelException($"Unable to deserialize the {nameof(KernelProcessEvent)} queue.");

        return eventContainer.Payload with { Data = TypeInfo.ConvertValue(eventContainer.DataTypeName, eventContainer.Payload.Data) };
    }
}
