using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Microsoft.SemanticKernel.Process.Runtime;

namespace Microsoft.SemanticKernel.Process.Serialization;

/// <summary>
/// Serializer for <see cref="ProcessMessage"/> objects. Includes type info for <see cref="ProcessMessage.TargetEventData"/>
/// and each entry of <see cref="ProcessMessage.Values"/>.
/// </summary>
internal static class ProcessMessageSerializer
{
    /// <summary>
    /// Serializes a <see cref="ProcessMessage"/> to JSON, capturing type information for its polymorphic payloads.
    /// </summary>
    /// <param name="processMessage">The message to serialize.</param>
    /// <returns>The serialized JSON string.</returns>
    public static string ToJson(this ProcessMessage processMessage)
    {
        Dictionary<string, string?> valueTypeNames =
            processMessage.Values.ToDictionary(
                kvp => kvp.Key,
                kvp => TypeInfo.GetAssemblyQualifiedType(kvp.Value));

        MessageContainer containedMessage =
            new(TypeInfo.GetAssemblyQualifiedType(processMessage.TargetEventData), valueTypeNames, processMessage);

        return JsonSerializer.Serialize(containedMessage);
    }

    /// <summary>
    /// Deserializes a set of JSON strings back into <see cref="ProcessMessage"/> objects, restoring the type of each polymorphic payload.
    /// </summary>
    /// <param name="jsonMessages">The JSON strings to deserialize.</param>
    /// <returns>The deserialized messages.</returns>
    /// <exception cref="KernelException">Thrown if any message fails deserialization.</exception>
    public static IList<ProcessMessage> ToProcessMessages(this IEnumerable<string> jsonMessages)
    {
        return Deserialize().ToArray();

        IEnumerable<ProcessMessage> Deserialize()
        {
            foreach (string json in jsonMessages)
            {
                MessageContainer messageContainer =
                    JsonSerializer.Deserialize<MessageContainer>(json) ??
                    throw new KernelException($"Unable to deserialize the {nameof(ProcessMessage)} queue.");

                yield return Process(messageContainer);
            }
        }
    }

    /// <summary>
    /// Restores the polymorphic payloads of a deserialized <see cref="MessageContainer"/>.
    /// </summary>
    private static ProcessMessage Process(MessageContainer messageContainer)
    {
        ProcessMessage message = messageContainer.Message;

        object? targetEventData = TypeInfo.ConvertValue(messageContainer.DataTypeName, message.TargetEventData);

        Dictionary<string, object?> values =
            message.Values.ToDictionary(
                kvp => kvp.Key,
                kvp => TypeInfo.ConvertValue(
                    messageContainer.ValueTypeNames.TryGetValue(kvp.Key, out string? typeName) ? typeName : null,
                    kvp.Value));

        return message with { TargetEventData = targetEventData, Values = values };
    }
}
